// Evaluate server trust; only proceed if it validates
- (void)URLSession:(NSURLSession *)s
 didReceiveChallenge:(NSURLAuthenticationChallenge *)ch
 completionHandler:(void (^)(NSURLSessionAuthChallengeDisposition, NSURLCredential *))done {
    SecTrustRef trust = ch.protectionSpace.serverTrust;
    CFErrorRef err = NULL;
    if (trust && SecTrustEvaluateWithError(trust, &err)) {
        done(NSURLSessionAuthChallengeUseCredential,
             [NSURLCredential credentialForTrust:trust]);
    } else {
        done(NSURLSessionAuthChallengeCancelAuthenticationChallenge, nil);
    }
}
